SOURCES = json.loads("{\"claim\": \"agentops.bronze.claim\", \"organization\": \"agentops.bronze.organization\"}")
GRAIN = json.loads("{\"provider_claims_denial_monthly\": [\"provider_id\", \"provider_name\", \"provider_state\", \"claim_month\"]}")

# COMMAND ----------

results = []
for case in SUITE.get("cases", []):
    try:
        srcs = {s: make_df(spark, spark.table(full).schema, (case.get("inputs") or {}).get(s, [])) for s, full in SOURCES.items()}
        outs = build(spark, srcs)
        probs = []
        for tgt in set(case.get("expected") or {}) | set(case.get("expect_absent") or {}):
            if tgt not in outs:
                probs.append(f"build() returned no '{tgt}'")
                continue
            rows = [{k.lower(): v for k, v in r.asDict().items()} for r in outs[tgt].collect()]
            probs += compare_rows(rows, (case.get("expected") or {}).get(tgt), GRAIN.get(tgt, []), tgt,
                                  (case.get("expected_row_count") or {}).get(tgt), (case.get("expect_absent") or {}).get(tgt))
        results.append({"name": case.get("name"), "checks": case.get("checks", ""), "passed": not probs,
                        "detail": "; ".join(probs[:6]) or "matches expected rows", "kind": "acceptance"})
    except Exception as e:
        results.append({"name": case.get("name"), "checks": case.get("checks", ""), "passed": False,
                        "detail": f"{type(e).__name__}: {str(e)[:600]}", "kind": "acceptance"})
for r in results:
    print(("PASS " if r["passed"] else "FAIL ") + str(r["name"]) + " — " + r["checks"] + ("" if r["passed"] else "\n     " + r["detail"]))
dbutils.notebook.exit(json.dumps({"kind": "acceptance", "suite": "4ac0800cfeb35ce3", "results": results}))